def __getattr__(name: str) -> Any:
    """__getattr__。

    参数说明：
    :param name: 参数 name
    :return: 返回处理结果。
    """
    if name in _EXPORTS:
        return getattr(importlib.import_module(_EXPORTS[name]), name)
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

